import { GoogleGenAI, Type } from "@google/genai";
import type { Game } from "../types";

const aiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Define the JSON schema for the prediction response to ensure structured output from the model.
export const predictionSchema = {
  type: Type.OBJECT,
  properties: {
    winner: { 
      type: Type.STRING,
      description: "The predicted winning team."
    },
    loser: {
      type: Type.STRING,
      description: "The predicted losing team."
    },
    confidence: {
      type: Type.STRING,
      description: "Confidence level of the prediction (High, Medium, or Low).",
      enum: ["High", "Medium", "Low"]
    },
    confidenceScore: {
      type: Type.NUMBER,
      description: "A numerical confidence score between 0 and 1 (e.g., 0.85 for 85%)."
    },
    ev: {
      type: Type.NUMBER,
      description: "Calculated +EV (Expected Value) percentage based on sharp bookmaker lines."
    },
    kellyRecommendation: {
      type: Type.STRING,
      description: "Suggested bet size using Kelly Criterion."
    },
    analysis: {
      type: Type.STRING,
      description: "A sharp, deep-dive analysis including WEATHER impact, REFEREE trends, and Defense vs Position (DvP) context."
    },
    gameScript: {
      type: Type.ARRAY,
      description: "A structured timeline of the simulated game flow.",
      items: {
        type: Type.OBJECT,
        properties: {
          phase: { type: Type.STRING, description: "Phase name" },
          description: { type: Type.STRING, description: "Detailed event simulation." }
        },
        required: ["phase", "description"]
      }
    },
    statComparison: {
      type: Type.ARRAY,
      description: "Comparison of 3 KEY advanced metrics relevant to this specific game.",
      items: {
        type: Type.OBJECT,
        properties: {
          statName: { type: Type.STRING },
          homeValue: { type: Type.STRING },
          awayValue: { type: Type.STRING },
          advantage: { type: Type.STRING, enum: ["Home", "Away", "Push"] }
        }
      }
    },
    injuries: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    trends: {
      type: Type.ARRAY,
      items: { type: Type.STRING }
    },
    odds: {
      type: Type.OBJECT,
      properties: {
        winner: { type: Type.STRING },
        loser: { type: Type.STRING }
      },
      required: ["winner", "loser"]
    },
    oddsDetails: {
      type: Type.OBJECT,
      properties: {
        winnerOpen: { type: Type.STRING },
        winnerCurrent: { type: Type.STRING },
        movement: { type: Type.STRING, enum: ["Steam", "Fading", "Stable"] },
        sharpConsensus: { type: Type.STRING },
        publicConsensus: { type: Type.STRING },
        bookmakers: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              book: { type: Type.STRING },
              odds: { type: Type.STRING },
              value: { type: Type.STRING, enum: ["Best", "Average", "Poor"] }
            }
          }
        }
      },
      required: ["winnerOpen", "winnerCurrent", "movement", "bookmakers"]
    },
    matchupHistory: {
        type: Type.ARRAY,
        items: {
             type: Type.OBJECT,
             properties: {
                 date: { type: Type.STRING },
                 homeTeam: { type: Type.STRING },
                 homeScore: { type: Type.STRING },
                 awayTeam: { type: Type.STRING },
                 awayScore: { type: Type.STRING },
                 winner: { type: Type.STRING }
             }
        }
    },
    props: {
        type: Type.ARRAY,
        description: "Top 5 player props with line comparison and performance history.",
        items: {
            type: Type.OBJECT,
            properties: {
                player: { type: Type.STRING },
                bet: { type: Type.STRING },
                line: { type: Type.STRING },
                stat: { type: Type.STRING },
                type: { type: Type.STRING, enum: ["MORE", "LESS"] },
                odds: { type: Type.STRING },
                probability: { type: Type.STRING },
                ev: { type: Type.NUMBER },
                analysis: { type: Type.STRING },
                isBestValue: { type: Type.BOOLEAN },
                homeAvg: { type: Type.STRING },
                awayAvg: { type: Type.STRING },
                lineComparison: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      book: { type: Type.STRING },
                      line: { type: Type.STRING },
                      odds: { type: Type.STRING }
                    }
                  }
                },
                performanceHistory: {
                  type: Type.ARRAY,
                  description: "The player's results for this specific stat over the last 3 games.",
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      date: { type: Type.STRING },
                      opponent: { type: Type.STRING },
                      actualValue: { type: Type.STRING, description: "The actual stat recorded, e.g. '28'" },
                      hit: { type: Type.BOOLEAN, description: "True if the MORE/LESS prediction would have hit based on CURRENT line." }
                    },
                    required: ["date", "opponent", "actualValue", "hit"]
                  }
                }
            },
            required: ["player", "bet", "line", "stat", "type", "odds", "probability", "analysis", "lineComparison", "performanceHistory"]
        }
    }
  },
  required: ["winner", "loser", "confidence", "confidenceScore", "analysis", "gameScript", "statComparison", "injuries", "odds", "oddsDetails", "props", "trends"]
};

export const ai = aiInstance;

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const sportQuery = sport === 'NFL' ? 'NFL Football' : sport;
  const prompt = `Fetch the current ${sportQuery} schedule, live scores, and REAL-TIME betting odds (spread, total, moneyline) for TODAY. 
  Ensure all data is precise and "refined" - do not include placeholders. 
  If a game is live, include the current score and clock. 
  Return STRICT JSON in this format: { "games": [{ "id": "uuid", "homeTeam": "string", "awayTeam": "string", "league": "string", "time": "string", "date": "string", "status": "Scheduled|Live|Finished", "score": "string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }.`;

  try {
    const response = await aiInstance.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }], 
        temperature: 0.1,
        responseMimeType: 'application/json'
      }
    });

    const text = response.text || '';
    const data = JSON.parse(text);
    return data.games || [];
  } catch (error) {
    console.error("Schedule Fetch Error:", error);
    return [];
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { ai, predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) {
        return JSON.parse(storedSettings);
      }
    } catch (error) {
      console.error("Failed to parse settings from localStorage", error);
    }
    return {
      preferredSport: 'NFL',
      defaultConfidenceFilter: 'All',
      oddsFormat: 'American',
    };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);

  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);

  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);

  // Pick Slip State
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => {
    setSelectedSport(settings.preferredSport);
  }, [settings.preferredSport]);

  // Reset selected game when sport changes
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    if (chatRef.current) {
        chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  const handleOpenToken = useCallback(() => {
    setIsTokenModalOpen(true);
  }, []);

  const handleCloseToken = useCallback(() => {
    setIsTokenModalOpen(false);
  }, []);

  const handleSaveSettings = useCallback((newSettings: UserSettings) => {
    setSettings(newSettings);
    try {
        localStorage.setItem('prognosSettings', JSON.stringify(newSettings));
    } catch (error) {
        console.error("Failed to save settings to localStorage", error);
    }
    setIsSettingsOpen(false);
  }, []);

  const handleTogglePick = useCallback((prop: PropBet) => {
    setPickSlip(prev => {
        const exists = prev.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
        if (exists) {
            return prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line));
        } else {
            if (prev.length >= 5) {
                return prev;
            }
            setIsHistorySidebarOpen(true);
            return [...prev, prop];
        }
    });
  }, []);

  const handleRemoveFromSlip = useCallback((prop: PropBet) => {
    setPickSlip(prev => prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line)));
  }, []);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) {
      setError('Please select a game from the schedule.');
      return;
    }
    setIsLoading(true);
    setError(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setShowSuggestions(false);

    const gameContext = selectedGame.status === 'Live' 
        ? `LIVE (${selectedGame.score}, ${selectedGame.time})`
        : `Scheduled: ${selectedGame.date} ${selectedGame.time}`;

    const prompt = `
      PERFORM DEEP AI ANALYSIS for ${selectedGame.league}: "${selectedGame.homeTeam}" vs "${selectedGame.awayTeam}" (${gameContext}).

      CORE MANDATE: 
      1. **Search & Learn**: Use Google Search to find advanced predictive models for this matchup (DVOA, KenPom, ELO). Seek out sharp consensus from Pinnacle/Circa.
      2. **Market Comparison**: Search and compare lines across Betr, PrizePicks, Underdog, and Sleeper for all props.
      3. **History Deep-Dive**: For every player prop, find the ACTUAL results of their LAST 3 GAMES. Mark them as hits/misses based on the current line.
      4. **Precision Check**: ONLY return "High" confidence if the mathematical edge exceeds 65%. 
      5. **No Placeholders**: Ensure every field is filled with refined, specific data. Do not say "unrefined".

      GOAL: Find the HIGHEST POSSIBILITY "Mathematical Strike".
      Output STRICT JSON only.
    `;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-3-pro-preview',
        config: {
          systemInstruction: `You are Pro N os, a profit-maximizing AI engineer.
          - Prioritize identifying >65% edges with mathematical precision.
          - Use live search data to ensure all predictions are "refined" and current.
          - Compare lines between Betr, PrizePicks, Underdog.
          - ALWAYS provide last 3 games performanceHistory for props.
          - Return JSON only. No text preamble.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
          tools: [{ googleSearch: {} }]
        }
      });

      setChat(newChat);
      const response = await newChat.sendMessage({ message: prompt });
      const text = response.text || '';

      try {
        const parsedPrediction = JSON.parse(text) as Prediction;
        setPrediction(parsedPrediction);
        setMessages([{ role: 'model', content: parsedPrediction }]);
        setShowSuggestions(true);
      } catch (parseError) {
        console.error("JSON Parse Error:", parseError, text);
        setError('Market stream synchronization failed. Please retry for refined data.');
      }
    } catch (err) {
      console.error("Prediction Error:", err);
      setError('An error occurred during heavy analysis. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;

    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    setShowSuggestions(false);

    try {
        const response = await chat.sendMessage({ message: text });
        const responseText = response.text || "I couldn't generate a refined response.";
        const modelMsg: ChatMessage = { role: 'model', content: responseText };
        setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
        console.error("Chat Error:", error);
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine timeout. Please try again." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={handleOpenSettings} onOpenToken={handleOpenToken} />

      <main className={`container mx-auto px-4 py-6 max-w-4xl relative z-0 transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>

        {error && (
            <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex items-center justify-between animate-fade-in backdrop-blur-md">
                <span className="text-sm font-semibold">{error}</span>
                <button onClick={() => setError(null)} className="text-red-400 hover:text-white text-lg">&times;</button>
            </div>
        )}

        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8 animate-fade-in">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule 
                    sport={selectedSport}
                    selectedGame={selectedGame}
                    onSelectGame={(game) => {
                        setSelectedGame(game);
                        setError(null);
                    }}
                />

                {selectedGame && (
                    <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20 pointer-events-none">
                         <button
                            onClick={handlePredict}
                            className="pointer-events-auto bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.6)] hover:shadow-[0_0_70px_rgba(245,158,11,0.8)] transform hover:scale-105 active:scale-95 transition-all duration-300 flex items-center gap-3 group"
                        >
                            <svg className="w-7 h-7 group-hover:animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE HIGH-PROBABILITY MODELS
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? (
            <Loader />
        ) : (
            <div className="space-y-4 animate-fade-in">
                 <button 
                    onClick={() => {
                        setPrediction(null);
                        setMessages([]);
                        setChat(null);
                    }}
                    className="flex items-center gap-2 text-stone-500 hover:text-white mb-2 transition-colors text-xs font-black uppercase tracking-widest"
                 >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Back to Feed
                 </button>

                 <ChatInterface 
                    messages={messages}
                    isReplying={isReplying}
                    onSendMessage={handleSendMessage}
                    oddsFormat={settings.oddsFormat}
                    onAnalyzeProp={(prop) => handleSendMessage(`Deep dive analysis for ${prop.player} ${prop.stat}. compare lines between all books and show last 5 game trends.`)}
                    pickSlip={pickSlip}
                    onTogglePick={handleTogglePick}
                    onSearchPlayer={(player) => handleSendMessage(`Analyze ${player}'s highest hit-rate prop for today. compare PrizePicks, Betr, and Underdog.`)}
                 />

                 {showSuggestions && prediction && (
                    <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />
                 )}
            </div>
        )}
      </main>

      <PerformanceSidebar 
        activePicks={pickSlip} 
        onClose={() => setIsHistorySidebarOpen(false)}
      />

      <PickSlip 
        picks={pickSlip} 
        onRemove={handleRemoveFromSlip}
        onAnalyze={() => handleSendMessage(`Analyze my current slip: ${pickSlip.map(p => `${p.player} ${p.type} ${p.line} ${p.stat}`).join(', ')}. Check for negative correlation and Combined win %`)}
      />

      <Footer />
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={handleCloseSettings} 
        currentSettings={settings}
        onSave={handleSaveSettings}
      />
      <TokenomicsModal 
        isOpen={isTokenModalOpen}
        onClose={handleCloseToken}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, memo } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const fetchGames = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      setGames(fetchedGames);
      if (fetchedGames.length === 0) {
        setError(`No live or scheduled ${sport} matchups found.`);
      }
    } catch (err) {
      setError('Network sync interrupted. Retrying...');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchGames();
  }, [sport]);

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-6">
        <div className="relative w-12 h-12">
           <div className="absolute inset-0 border-4 border-amber-500/20 rounded-full"></div>
           <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
        </div>
        <div className="text-center">
            <p className="text-amber-500 font-black text-sm uppercase tracking-[0.2em] animate-pulse">Synchronizing Market Feeds</p>
            <p className="text-zinc-600 text-[10px] font-bold mt-1 uppercase">Fetching Real-Time Odds & Rosters</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
        <div className="text-center py-12 border-2 border-dashed border-zinc-800 rounded-3xl">
            <p className="text-zinc-400 text-sm font-semibold mb-6">{error}</p>
            <button 
                onClick={fetchGames}
                className="text-xs font-black uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-amber-500 px-6 py-2.5 rounded-full transition-all"
            >
                Manual Sync
            </button>
        </div>
    );
  }

  return (
    <div className="space-y-4 w-full">
      <div className="flex justify-between items-center mb-2 px-2">
        <div className="text-[10px] text-zinc-500 uppercase tracking-[0.2em] font-black flex items-center gap-2">
           <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></div>
           Live Game Stream
        </div>
        <button 
            onClick={fetchGames} 
            className="text-[10px] text-amber-500/80 hover:text-amber-500 flex items-center gap-1.5 transition-colors font-black uppercase tracking-widest"
        >
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                <path fillRule="evenodd" d="M15.312 11.424a5.5 5.5 0 01-9.201 2.466l-.312-.311h2.433a.75.75 0 000-1.5H3.989a.75.75 0 00-.75.75v4.242a.75.75 0 001.5 0v-2.43l.31.31a7 7 0 0011.712-3.138.75.75 0 00-1.449-.39zm1.23-3.723a.75.75 0 00.219-.53V2.929a.75.75 0 00-1.5 0v2.433l-.31-.31a7 7 0 00-11.712 3.138.75.75 0 001.449.39 5.5 5.5 0 019.201-2.466l.312.312h-2.433a.75.75 0 000 1.5h4.242z" clipRule="evenodd" />
            </svg>
            Refine Data
        </button>
      </div>

      <div className="grid gap-3 max-h-[450px] overflow-y-auto pr-2 custom-scrollbar">
        {games.map((game) => {
          const isSelected = selectedGame?.id === game.id;
          const isLive = game.status === 'Live';
          const timeText = (game.time || '').toLowerCase();
          const isLateGame = timeText.includes('q3') || timeText.includes('q4') || timeText.includes('3rd') || timeText.includes('4th') || timeText.includes('ot');

          return (
            <button
              key={game.id}
              onClick={() => onSelectGame(game)}
              className={`relative group w-full text-left p-5 rounded-2xl border-2 transition-all duration-300 ${
                isSelected
                  ? 'bg-zinc-900 border-amber-500 shadow-[0_0_30px_rgba(245,158,11,0.15)] ring-1 ring-amber-500/20'
                  : isLive
                    ? 'bg-gradient-to-br from-[#120404] to-black border-red-900/30 hover:border-red-600/50'
                    : 'bg-zinc-950/50 border-zinc-900 hover:border-zinc-700 hover:bg-zinc-900'
              }`}
            >
              {isLive && (
                <span className={`absolute -top-[2px] right-4 px-3 py-1 rounded-b-lg border-x border-b z-10 flex items-center gap-2 ${
                    isLateGame 
                        ? 'bg-amber-500/10 border-amber-500/30 text-amber-400' 
                        : 'bg-red-600/10 border-red-500/30 text-red-500'
                }`}>
                    <span className="relative flex h-1.5 w-1.5">
                        <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                        <span className={`relative inline-flex rounded-full h-1.5 w-1.5 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                    </span>
                    <span className="text-[9px] font-black tracking-widest uppercase">
                        {isLateGame ? 'Clutch Mode' : 'Live Engine'}
                    </span>
                </span>
              )}

              <div className="flex items-center justify-between gap-6">
                {/* Home Team */}
                <div className="flex-1 flex flex-col items-center gap-3">
                    <div className="relative">
                        <img 
                            src={`https://avatar.vercel.sh/${encodeURIComponent(game.homeTeam)}.png?size=80`} 
                            alt={game.homeTeam}
                            className={`w-12 h-12 rounded-full bg-zinc-900 border-2 transition-all ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`}
                        />
                    </div>
                    <span className={`text-xs font-black text-center leading-tight uppercase tracking-tighter ${isSelected ? 'text-white' : 'text-zinc-400'}`}>
                        {game.homeTeam}
                    </span>
                </div>

                {/* Match Center */}
                <div className="flex flex-col items-center justify-center min-w-[100px]">
                   {isLive && game.score ? (
                        <div className="flex flex-col items-center gap-1.5">
                            <div className="text-2xl font-black text-white tracking-widest tabular-nums">
                                {game.score}
                            </div>
                            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-widest border transition-colors ${
                                isLateGame 
                                    ? 'bg-amber-500 text-black border-amber-400' 
                                    : 'bg-zinc-900 text-red-500 border-red-900/50'
                            }`}>
                                {game.time}
