                     <div className="flex items-center gap-2">
                        <div className="w-1 h-1 bg-zinc-800 rounded-full animate-pulse"></div>
                        <span className="text-[9px] text-zinc-700 font-black uppercase tracking-widest">Real-Time Odds Syncing</span>
                     </div>
                  )}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { ai, predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) {
        return JSON.parse(storedSettings);
      }
    } catch (error) {
      console.error("Failed to parse settings from localStorage", error);
    }
    return {
      preferredSport: 'NFL',
      defaultConfidenceFilter: 'All',
      oddsFormat: 'American',
    };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);

  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);

  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);

  // Pick Slip State
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => {
    setSelectedSport(settings.preferredSport);
  }, [settings.preferredSport]);

  // Reset selected game when sport changes
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    if (chatRef.current) {
        chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleOpenSettings = useCallback(() => {
    setIsSettingsOpen(true);
  }, []);

  const handleCloseSettings = useCallback(() => {
    setIsSettingsOpen(false);
  }, []);

  const handleOpenToken = useCallback(() => {
    setIsTokenModalOpen(true);
  }, []);

  const handleCloseToken = useCallback(() => {
    setIsTokenModalOpen(false);
  }, []);

  const handleSaveSettings = useCallback((newSettings: UserSettings) => {
    setSettings(newSettings);
    try {
        localStorage.setItem('prognosSettings', JSON.stringify(newSettings));
    } catch (error) {
        console.error("Failed to save settings to localStorage", error);
    }
    setIsSettingsOpen(false);
  }, []);

  const handleTogglePick = useCallback((prop: PropBet) => {
    setPickSlip(prev => {
        const exists = prev.some(p => p.player === prop.player && p.stat === prop.stat && p.line === prop.line);
        if (exists) {
            return prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line));
        } else {
            if (prev.length >= 5) {
                return prev;
            }
            setIsHistorySidebarOpen(true);
            return [...prev, prop];
        }
    });
  }, []);

  const handleRemoveFromSlip = useCallback((prop: PropBet) => {
    setPickSlip(prev => prev.filter(p => !(p.player === prop.player && p.stat === prop.stat && p.line === prop.line)));
  }, []);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) {
      setError('Please select a game from the schedule.');
      return;
    }
    setIsLoading(true);
    setError(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setShowSuggestions(false);

    const gameContext = selectedGame.status === 'Live' 
        ? `LIVE (${selectedGame.score}, ${selectedGame.time})`
        : `Scheduled: ${selectedGame.date} ${selectedGame.time}`;

    const prompt = `
      PERFORM RAPID DEEP AI ANALYSIS for ${selectedGame.league}: "${selectedGame.homeTeam}" vs "${selectedGame.awayTeam}" (${gameContext}).

      CORE MANDATE: 
      1. **Search & Learn**: Search for latest injury reports, Vegas sharp movement, and advanced predictive metrics.
      2. **Market Comparison**: Compare lines across Betr, PrizePicks, Underdog.
      3. **History**: Verify player prop results for the LAST 3 GAMES.
      4. **Speed & Precision**: Generate a high-probability model response immediately.

      Output STRICT JSON only.
    `;

    try {
      // Switched to gemini-3-flash-preview for enhanced speed
      const newChat = ai.chats.create({ 
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are Pro N os, a profit-maximizing AI engineer.
          - Prioritize identifying >65% edges with mathematical precision.
          - Use live search data to ensure all predictions are current.
          - ALWAYS provide last 3 games performanceHistory for props.
          - Return JSON only. No text preamble.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
          tools: [{ googleSearch: {} }]
        }
      });

      setChat(newChat);
      const response = await newChat.sendMessage({ message: prompt });
      const text = response.text || '';

      try {
        const parsedPrediction = JSON.parse(text) as Prediction;
        setPrediction(parsedPrediction);
        setMessages([{ role: 'model', content: parsedPrediction }]);
        setShowSuggestions(true);
      } catch (parseError) {
        console.error("JSON Parse Error:", parseError, text);
        setError('Market stream synchronization failed. Please retry for refined data.');
      }
    } catch (err) {
      console.error("Prediction Error:", err);
      setError('An error occurred during heavy analysis. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;

    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    setShowSuggestions(false);

    try {
        const response = await chat.sendMessage({ message: text });
        const responseText = response.text || "I couldn't generate a refined response.";
        const modelMsg: ChatMessage = { role: 'model', content: responseText };
        setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
        console.error("Chat Error:", error);
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine timeout. Please try again." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={handleOpenSettings} onOpenToken={handleOpenToken} />

      <main className={`container mx-auto px-4 py-6 max-w-4xl relative z-0 transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>

        {error && (
            <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex items-center justify-between animate-fade-in backdrop-blur-md">
                <span className="text-sm font-semibold">{error}</span>
                <button onClick={() => setError(null)} className="text-red-400 hover:text-white text-lg">&times;</button>
            </div>
        )}

        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8 animate-fade-in">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule 
                    sport={selectedSport}
                    selectedGame={selectedGame}
                    onSelectGame={(game) => {
                        setSelectedGame(game);
                        setError(null);
                    }}
                />

                {selectedGame && (
                    <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20 pointer-events-none">
                         <button
                            onClick={handlePredict}
                            className="pointer-events-auto bg-gradient-to-r from-amber-500 via-orange-500 to-amber-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.6)] hover:shadow-[0_0_70px_rgba(245,158,11,0.8)] transform hover:scale-105 active:scale-95 transition-all duration-300 flex items-center gap-3 group"
                        >
                            <svg className="w-7 h-7 group-hover:animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE HIGH-PROBABILITY MODELS
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? (
            <Loader />
        ) : (
            <div className="space-y-4 animate-fade-in">
                 <button 
                    onClick={() => {
                        setPrediction(null);
                        setMessages([]);
                        setChat(null);
                    }}
                    className="flex items-center gap-2 text-stone-500 hover:text-white mb-2 transition-colors text-xs font-black uppercase tracking-widest"
                 >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Back to Feed
                 </button>

                 <ChatInterface 
                    messages={messages}
                    isReplying={isReplying}
                    onSendMessage={handleSendMessage}
                    oddsFormat={settings.oddsFormat}
                    onAnalyzeProp={(prop) => handleSendMessage(`Deep dive analysis for ${prop.player} ${prop.stat}. compare lines between all books and show last 5 game trends.`)}
                    pickSlip={pickSlip}
                    onTogglePick={handleTogglePick}
                    onSearchPlayer={(player) => handleSendMessage(`Analyze ${player}'s highest hit-rate prop for today. compare PrizePicks, Betr, and Underdog.`)}
                 />

                 {showSuggestions && prediction && (
                    <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />
                 )}
            </div>
        )}
      </main>

      <PerformanceSidebar 
        activePicks={pickSlip} 
        onClose={() => setIsHistorySidebarOpen(false)}
      />

      <PickSlip 
        picks={pickSlip} 
        onRemove={handleRemoveFromSlip}
        onAnalyze={() => handleSendMessage(`Analyze my current slip: ${pickSlip.map(p => `${p.player} ${p.type} ${p.line} ${p.stat}`).join(', ')}. Check for negative correlation and Combined win %`)}
      />

      <Footer />
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={handleCloseSettings} 
        currentSettings={settings}
        onSave={handleSaveSettings}
      />
      <TokenomicsModal 
        isOpen={isTokenModalOpen}
        onClose={handleCloseToken}
      />
    </div>
  );
};

export default App;

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, SearchIcon, DoubleCheckIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string }> = {
    High: { bg: 'bg-green-950/40', text: 'text-green-400', border: 'border-green-500/40', accent: 'bg-green-500' },
    Medium: { bg: 'bg-amber-950/30', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500' },
    Low: { bg: 'bg-zinc-900/50', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-700' },
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, onAnalyzeProp, pickSlip = [], onTogglePick, onSearchPlayer }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');

  const [customPlayer, setCustomPlayer] = useState('');
  const [customLine, setCustomLine] = useState('');

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];
  const confidencePercentage = prediction.confidenceScore != null ? (prediction.confidenceScore * 100).toFixed(0) : 'N/A';

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return prediction.props.filter(prop => {
        const matchesType = typeFilter === 'All' || prop.type === typeFilter;
        const matchesSearch = (prop.player || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (prop.stat || '').toLowerCase().includes(searchQuery.toLowerCase());
        return matchesType && matchesSearch;
    });
  }, [prediction.props, typeFilter, searchQuery]);

  const handleCustomAnalyze = (e: React.FormEvent) => {
      e.preventDefault();
      if (customPlayer && customLine && onSearchPlayer) {
          onSearchPlayer(`Perform a PRECISION MARKET ARBITRAGE analysis for ${customPlayer} ${customLine}. Search Betr, PrizePicks, and Underdog. Identify discrepancies > 65% hit rate.`);
          setCustomPlayer('');
          setCustomLine('');
      }
  };

  const bestProp = useMemo(() => {
    if (!prediction.props || prediction.props.length === 0) return null;
    return [...prediction.props].sort((a, b) => parseInt(b.probability) - parseInt(a.probability))[0];
  }, [prediction.props]);

  return (
    <div className="space-y-6 w-full animate-fade-in">
       {/* Primary Prediction Banner */}
       <div className={`p-8 rounded-[2.5rem] border-2 ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-xl shadow-2xl relative overflow-hidden`}>
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-[100px] pointer-events-none -translate-y-1/2 translate-x-1/2"></div>

          <div className="flex flex-col md:flex-row justify-between items-center gap-8 relative z-10">
             <div className="flex items-center gap-6">
                 <div className="relative group">
                    <div className="absolute inset-0 bg-amber-500 rounded-full blur-lg opacity-20 group-hover:opacity-40 transition-opacity"></div>
                    <img 
                        src={`https://ui-avatars.com/api/?name=${encodeURIComponent(prediction.winner)}&background=f59e0b&color=000&size=128&bold=true`}
                        alt={prediction.winner}
                        className="w-24 h-24 rounded-full border-4 border-amber-500 shadow-2xl relative z-10"
                    />
                    <div className="absolute -bottom-2 -right-2 bg-green-500 rounded-full p-1.5 border-4 border-black z-20">
                        <CheckIcon className="w-4 h-4 text-black" />
                    </div>
                 </div>
                 <div>
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-amber-500/80">Refined AI Prediction</span>
                    <h2 className="text-4xl md:text-5xl font-black text-white mt-2 leading-none tracking-tighter">{prediction.winner}</h2>
                    <div className="flex items-center gap-3 mt-4">
                         <div className="h-1.5 w-32 bg-black/40 rounded-full overflow-hidden border border-white/5">
                            <div className={`h-full ${confidenceStyle.accent} shadow-[0_0_15px_rgba(245,158,11,0.4)]`} style={{ width: `${confidencePercentage}%` }}></div>
                         </div>
                         <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">{confidencePercentage}% Probability</span>
                    </div>
                 </div>
             </div>

             <div className="flex flex-col items-center md:items-end">
                 <div className={`px-6 py-3 rounded-2xl border-2 ${confidenceStyle.border} bg-black/60 backdrop-blur-md flex flex-col items-center shadow-lg`}>
                    <span className={`text-[10px] font-black uppercase tracking-[0.2em] mb-1 ${confidenceStyle.text}`}>Confidence</span>
                    <span className="text-3xl font-black text-white uppercase">{prediction.confidence}</span>
                 </div>
             </div>
          </div>

          <div className="mt-8 pt-6 border-t border-white/5">
              <p className="text-zinc-200 text-base md:text-lg leading-relaxed font-medium italic opacity-90">
                "{prediction.analysis}"
              </p>
          </div>
       </div>

       {/* Simulation Timeline Infographic */}
       {prediction.gameScript && (
          <div className="bg-zinc-950 rounded-3xl border border-zinc-900 p-8 relative overflow-hidden shadow-2xl">
              <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                 <AnalyticsIcon className="w-5 h-5 text-amber-500" />
                 Simulated Game Dynamics
              </h3>

              <div className="relative pl-10 space-y-10">
                  <div className="absolute left-4 top-2 bottom-2 w-[2px] bg-gradient-to-b from-amber-500 via-zinc-800 to-transparent"></div>

                  {prediction.gameScript.map((step, idx) => (
                      <div key={idx} className="relative group">
                          <div className="absolute -left-[31px] top-1.5 w-5 h-5 rounded-full bg-zinc-950 border-2 border-amber-500 group-hover:scale-125 transition-all duration-300 z-10 flex items-center justify-center">
                              <div className="w-1.5 h-1.5 rounded-full bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,1)]"></div>
                          </div>
                          <div className="flex flex-col">
                              <span className="text-[10px] font-black text-amber-500/60 uppercase tracking-widest mb-1.5">{step.phase}</span>
                              <p className="text-zinc-300 text-sm leading-relaxed font-medium border-l-2 border-transparent group-hover:border-amber-500/20 pl-4 -ml-4 transition-all">
                                {step.description}
                              </p>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
       )}

       {/* Mathematical Strike - High Probability Edge (70% Threshold) */}
       {bestProp && parseInt(bestProp.probability) >= 70 && (
          <div className="bg-gradient-to-br from-amber-500/10 to-zinc-950 rounded-[2.5rem] border-2 border-amber-500 p-8 shadow-[0_0_80px_rgba(245,158,11,0.15)] relative group overflow-hidden">
              <div className="absolute -bottom-10 -right-10 text-amber-500/5 text-9xl font-black italic select-none pointer-events-none uppercase">Strike</div>
