                  <div className="flex items-center gap-5">
                      <div className="bg-amber-500 p-3.5 rounded-2xl shadow-2xl shadow-amber-500/20">
                          <DoubleCheckIcon className="w-8 h-8 text-black" />
                      </div>
                      <div>
                          <h3 className="text-2xl font-black text-white tracking-tighter uppercase italic">Mathematical Strike</h3>
                          <div className="flex items-center gap-3 mt-1">
                             <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Efficiency Edge: {bestProp.probability}</span>
                             <div className="w-1 h-1 bg-zinc-800 rounded-full"></div>
                             <span className="text-[10px] font-black text-green-400 uppercase tracking-widest animate-pulse">Alpha Signal Detected</span>
                          </div>
                      </div>
                  </div>
              </div>

              <div className="space-y-6">
                <div className="bg-black/60 backdrop-blur-md rounded-[2rem] p-6 border border-amber-500/20 flex flex-col md:flex-row items-center justify-between gap-6 shadow-inner">
                    <div className="flex items-center gap-5">
                        <img src={`https://i.pravatar.cc/150?u=${encodeURIComponent(bestProp.player)}`} className="w-16 h-16 rounded-full border-2 border-amber-500 shadow-2xl object-cover" />
                        <div>
                            <span className="block text-white font-black text-2xl leading-tight tracking-tighter">{bestProp.player}</span>
                            <span className="text-amber-500 font-black text-sm uppercase tracking-widest flex items-center gap-2 mt-1">
                              {bestProp.type} {bestProp.line} {bestProp.stat}
                              <span className="px-2 py-0.5 bg-amber-500/10 rounded text-[9px]">Model Target</span>
                            </span>
                        </div>
                    </div>
                    <button 
                        onClick={() => onTogglePick && onTogglePick(bestProp)}
                        className="bg-amber-500 hover:bg-amber-400 text-black font-black px-10 py-4 rounded-2xl shadow-xl shadow-amber-500/10 transition-all transform hover:scale-105 active:scale-95 text-sm uppercase tracking-widest"
