                    <div className="absolute top-0 left-0 w-1 h-full bg-amber-500"></div>
                    <div className="flex items-center gap-2 mb-3">
                        <AnalyticsIcon className="w-4 h-4 text-amber-500" />
                        <span className="text-[10px] font-black text-amber-500 uppercase tracking-[0.2em]">Strike Rationale</span>
                    </div>
                    <p className="text-zinc-300 text-sm leading-relaxed italic">
                        {bestProp.analysis || `This selection qualifies as a Mathematical Strike due to a ${bestProp.probability} win probability derived from significant market divergence and historical matchup dominance. The current line shows a major discrepancy compared to sharp bookmaker aggregates.`}
