                                    ? filter === 'MORE' ? 'bg-green-500/10 text-green-400 border border-green-500/20 shadow-lg' : filter === 'LESS' ? 'bg-red-500/10 text-red-400 border border-red-500/20 shadow-lg' : 'bg-zinc-800 text-white border border-zinc-700 shadow-lg'
                                    : 'text-zinc-600 hover:text-zinc-400'
