                        {game.odds.moneyline && (
                             <div className="flex flex-col items-center">
                                <span className="text-[8px] font-black text-zinc-600 uppercase mb-0.5">ML</span>
                                <span className="text-[11px] font-black text-zinc-400 tabular-nums">{game.odds.moneyline}</span>
                            </div>
                        )}
                    </>
                  ) : (
                     <div className="flex items-center gap-2">
                        <div className="w-1 h-1 bg-zinc-800 rounded-full animate-pulse"></div>
                        <span className="text-[9px] text-zinc-700 font-black uppercase tracking-widest">Real-Time Odds Syncing</span>
                     </div>
                  )}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});

