  },
  required: ["winner", "loser", "confidence", "confidenceScore", "analysis", "gameScript", "statComparison", "injuries", "odds", "oddsDetails", "props", "trends"]
};

export const ai = getAI();

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `CRITICAL TASK: Search for ${sport} games occurring TODAY, ${today}. 

  PRIORITY: 
  1. LIVE GAMES (Show current score and time/quarter).
  2. UPCOMING GAMES (Show start time and betting lines: spread, moneyline, total).

  RULES:
  - Use real team names (e.g., Lakers, Chiefs).
  - Include current scores for live matches.
  - Set status to 'Live' for games currently playing.

  Return STRICT JSON:
  { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "score": "optional string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.2,
        responseMimeType: 'application/json'
      }
    });

    const text = response.text || '{}';
    const data = JSON.parse(text);
    return data.games || [];
  } catch (error) {
    console.error("Schedule Fetch Failed:", error);
    // Return empty list so UI can show retry state instead of crashing
    return [];
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const chatRef = useRef<HTMLDivElement>(null);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gameContext = selectedGame.status === 'Live' ? `LIVE (${selectedGame.score}, ${selectedGame.time})` : `Start: ${selectedGame.time}`;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: "You are Pro N os, a rapid sports analytics engine. Use search to find LIVE injury updates and betting splits. Return STRICT JSON.",
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
          tools: [{ googleSearch: {} }]
        }
      });

      const response = await newChat.sendMessage({ 
        message: `PERFORM RAPID ANALYSIS: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam} (${gameContext}). Analyze outcomes and top 5 player props. Focus on >65% hit rate props.` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      console.error("Prediction Failed:", err);
      setError(err?.message?.includes('Rpc') 
        ? "The analytics engine is temporarily overwhelmed. Please try a manual sync or select another game." 
        : "Real-time sync error. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;
    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    try {
        const response = await chat.sendMessage({ message: text });
        setMessages(prev => [...prev, { role: 'model', content: response.text || "I couldn't refine that data." }]);
    } catch (e) {
        setMessages(prev => [...prev, { role: 'model', content: "Engine timeout. Please refresh the game feed." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={() => setIsSettingsOpen(true)} onOpenToken={() => setIsTokenModalOpen(true)} />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>
        {error && (
            <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center animate-fade-in">
                <span className="text-xs font-bold uppercase tracking-tight">{error}</span>
                <button onClick={() => setError(null)} className="text-xl">&times;</button>
            </div>
        )}
        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                {selectedGame && (
                    <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                         <button onClick={handlePredict} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.5)] transform hover:scale-105 transition-all flex items-center gap-3">
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            GENERATE TODAY'S MODEL
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? <Loader /> : (
            <div className="space-y-4">
                 <button onClick={() => { setPrediction(null); setMessages([]); setChat(null); }} className="text-stone-500 hover:text-white mb-2 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg> Back to Feed
                 </button>
                 <ChatInterface messages={messages} isReplying={isReplying} onSendMessage={handleSendMessage} oddsFormat={settings.oddsFormat} pickSlip={pickSlip} onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} />
                 {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
            </div>
        )}
      </main>
      <PerformanceSidebar activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => handleSendMessage("Analyze my slip risk.")} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, memo, useMemo, useRef } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [countdown, setCountdown] = useState<number>(30);

  const refreshIntervalRef = useRef<number | null>(null);
  const countdownIntervalRef = useRef<number | null>(null);

  const fetchGames = async (silent = false) => {
    if (!silent) setIsLoading(true);
    else setIsRefreshing(true);

    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      if (fetchedGames && fetchedGames.length > 0) {
        setGames(fetchedGames);
        setLastUpdated(new Date());
        setCountdown(30);
      } else if (!silent) {
        setError(`No live or scheduled ${sport} matchups found for today.`);
      }
    } catch (err) {
      if (!silent) setError('Network sync interrupted. Retrying...');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  // Initial fetch and sport change
  useEffect(() => {
    fetchGames();

    // Clear existing intervals
    if (refreshIntervalRef.current) window.clearInterval(refreshIntervalRef.current);
    if (countdownIntervalRef.current) window.clearInterval(countdownIntervalRef.current);

    // Set 30s refresh interval
    refreshIntervalRef.current = window.setInterval(() => {
      fetchGames(true);
    }, 30000);

    // Set 1s countdown interval
    countdownIntervalRef.current = window.setInterval(() => {
      setCountdown(prev => (prev > 0 ? prev - 1 : 30));
    }, 1000);

    return () => {
      if (refreshIntervalRef.current) window.clearInterval(refreshIntervalRef.current);
      if (countdownIntervalRef.current) window.clearInterval(countdownIntervalRef.current);
    };
  }, [sport]);

  // Sort games: Live first, then Scheduled, then Finished
  const sortedGames = useMemo(() => {
    return [...games].sort((a, b) => {
      const statusOrder = { 'Live': 0, 'Scheduled': 1, 'Finished': 2 };
      return (statusOrder[a.status] ?? 3) - (statusOrder[b.status] ?? 3);
    });
  }, [games]);

  const formatTime = (date: Date) => {
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  if (isLoading && games.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-6">
        <div className="relative w-12 h-12">
           <div className="absolute inset-0 border-4 border-amber-500/20 rounded-full"></div>
           <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
        </div>
        <div className="text-center">
            <p className="text-amber-500 font-black text-sm uppercase tracking-[0.2em] animate-pulse">Synchronizing Market Feeds</p>
            <p className="text-zinc-600 text-[10px] font-bold mt-1 uppercase">Fetching Real-Time Odds & Rosters</p>
        </div>
      </div>
    );
  }

  if (error && games.length === 0) {
    return (
        <div className="text-center py-12 border-2 border-dashed border-zinc-800 rounded-3xl">
            <p className="text-zinc-400 text-sm font-semibold mb-6">{error}</p>
            <button 
                onClick={() => fetchGames()}
                className="text-xs font-black uppercase tracking-widest bg-zinc-800 hover:bg-zinc-700 text-amber-500 px-6 py-2.5 rounded-full transition-all"
            >
                Manual Sync
            </button>
        </div>
    );
  }

  return (
    <div className="space-y-4 w-full">
      <div className="flex justify-between items-end mb-2 px-2">
        <div className="flex flex-col gap-1">
            <div className="text-[10px] text-zinc-500 uppercase tracking-[0.2em] font-black flex items-center gap-2">
                <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></div>
                Live Game Stream
            </div>
            <div className="text-[8px] font-bold text-zinc-700 uppercase tracking-widest flex items-center gap-2">
                Last Sync: {formatTime(lastUpdated)} 
                <span className="text-amber-500/40">•</span>
                Next Refresh in {countdown}s
            </div>
        </div>

        <div className="flex items-center gap-3">
            {isRefreshing && (
                <span className="text-[9px] text-amber-500 font-black animate-pulse uppercase tracking-tighter">
                    Updating Odds...
                </span>
            )}
            <button 
                onClick={() => fetchGames()} 
                disabled={isLoading || isRefreshing}
                className="text-[10px] text-amber-500/80 hover:text-amber-500 flex items-center gap-1.5 transition-colors font-black uppercase tracking-widest disabled:opacity-50"
            >
                Manual Refine
            </button>
        </div>
      </div>

      <div className="grid gap-3 max-h-[450px] overflow-y-auto pr-2 custom-scrollbar">
        {sortedGames.map((game) => {
          const isSelected = selectedGame?.id === game.id;
          const isLive = game.status === 'Live';
          const timeText = (game.time || '').toLowerCase();
          const isLateGame = timeText.includes('q3') || timeText.includes('q4') || timeText.includes('3rd') || timeText.includes('4th') || timeText.includes('ot');

          return (
            <button
              key={game.id}
              onClick={() => onSelectGame(game)}
              className={`relative group w-full text-left p-5 rounded-2xl border-2 transition-all duration-300 ${
                isSelected
                  ? 'bg-zinc-900 border-amber-500 shadow-[0_0_30px_rgba(245,158,11,0.15)] ring-1 ring-amber-500/20'
                  : isLive
                    ? 'bg-gradient-to-br from-[#120404] to-black border-red-900/40 hover:border-red-600/60 shadow-[inset_0_0_20px_rgba(220,38,38,0.05)]'
                    : 'bg-zinc-950/50 border-zinc-900 hover:border-zinc-700 hover:bg-zinc-900'
              }`}
            >
              {isLive && (
                <span className={`absolute -top-[2px] right-4 px-3 py-1 rounded-b-lg border-x border-b z-10 flex items-center gap-2 ${
                    isLateGame 
                        ? 'bg-amber-500/10 border-amber-500/30 text-amber-400' 
                        : 'bg-red-600/20 border-red-500/40 text-red-500 shadow-[0_0_15px_rgba(220,38,38,0.2)]'
                }`}>
                    <span className="relative flex h-1.5 w-1.5">
                        <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                        <span className={`relative inline-flex rounded-full h-1.5 w-1.5 ${isLateGame ? 'bg-amber-500' : 'bg-red-500'}`}></span>
                    </span>
                    <span className="text-[9px] font-black tracking-widest uppercase">
                        {isLateGame ? 'Clutch Mode' : 'Live Now'}
                    </span>
                </span>
              )}

              <div className="flex items-center justify-between gap-6">
                {/* Home Team */}
                <div className="flex-1 flex flex-col items-center gap-3">
                    <div className="relative">
                        <img 
                            src={`https://avatar.vercel.sh/${encodeURIComponent(game.homeTeam)}.png?size=80`} 
                            alt={game.homeTeam}
                            className={`w-12 h-12 rounded-full bg-zinc-900 border-2 transition-all ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`}
                        />
                    </div>
                    <span className={`text-xs font-black text-center leading-tight uppercase tracking-tighter ${isSelected ? 'text-white' : 'text-zinc-400'}`}>
                        {game.homeTeam}
                    </span>
                </div>

                {/* Match Center */}
                <div className="flex flex-col items-center justify-center min-w-[100px]">
                   {isLive && game.score ? (
                        <div className="flex flex-col items-center gap-1.5">
                            <div className="text-2xl font-black text-white tracking-widest tabular-nums animate-pulse">
                                {game.score}
                            </div>
                            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-widest border transition-colors ${
                                isLateGame 
                                    ? 'bg-amber-500 text-black border-amber-400' 
                                    : 'bg-zinc-900 text-red-500 border-red-900/50'
                            }`}>
                                {game.time}
                            </span>
                        </div>
                   ) : (
                        <div className="flex flex-col items-center">
                            <span className="text-[10px] font-black text-zinc-700 mb-1.5 uppercase tracking-widest">Kickoff</span>
                            <span className="text-[11px] text-white font-black uppercase text-center bg-zinc-900 px-3 py-1 rounded-md border border-zinc-800 tracking-wider shadow-inner">
                                {game.date === 'Today' ? game.time : `${game.date}`}
                            </span>
                        </div>
                   )}
                </div>

                {/* Away Team */}
                <div className="flex-1 flex flex-col items-center gap-3">
                    <div className="relative">
                        <img 
                            src={`https://avatar.vercel.sh/${encodeURIComponent(game.awayTeam)}.png?size=80`} 
                            alt={game.awayTeam}
                            className={`w-12 h-12 rounded-full bg-zinc-900 border-2 transition-all ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`}
                        />
                    </div>
                    <span className={`text-xs font-black text-center leading-tight uppercase tracking-tighter ${isSelected ? 'text-white' : 'text-zinc-400'}`}>
                        {game.awayTeam}
                    </span>
                </div>
              </div>

              {/* Refined Odds Bar */}
              <div className={`mt-5 pt-4 flex flex-wrap justify-center items-center gap-4 border-t ${isLive ? 'border-red-900/20' : 'border-zinc-900'}`}>
                  {(game.odds?.spread || game.odds?.total || game.odds?.moneyline) ? (
                    <>
                        {game.odds.spread && (
                            <div className="flex flex-col items-center">
                                <span className="text-[8px] font-black text-zinc-600 uppercase mb-0.5">Spread</span>
                                <span className="text-[11px] font-black text-amber-500 tabular-nums">{game.odds.spread}</span>
                            </div>
                        )}
                        {game.odds.total && (
                            <div className="flex flex-col items-center">
                                <span className="text-[8px] font-black text-zinc-600 uppercase mb-0.5">Total</span>
                                <span className="text-[11px] font-black text-zinc-300 tabular-nums">{game.odds.total}</span>
                            </div>
                        )}
                        {game.odds.moneyline && (
                             <div className="flex flex-col items-center">
                                <span className="text-[8px] font-black text-zinc-600 uppercase mb-0.5">ML</span>
                                <span className="text-[11px] font-black text-zinc-400 tabular-nums">{game.odds.moneyline}</span>
                            </div>
                        )}
                    </>
                  ) : (
                     <div className="flex items-center gap-2">
                        <div className="w-1 h-1 bg-zinc-800 rounded-full animate-pulse"></div>
                        <span className="text-[9px] text-zinc-700 font-black uppercase tracking-widest">Real-Time Odds Syncing</span>
                     </div>
                  )}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});

