    winner: { type: Type.STRING },
    loser: { type: Type.STRING },
    confidence: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
    confidenceScore: { type: Type.NUMBER },
    eliteSignal179: { 
      type: Type.BOOLEAN, 
      description: "True if the pick passes the 179-point variance simulation check (>85% hit rate)." 
    },
    analysis: { type: Type.STRING },
    gameScript: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          phase: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ["phase", "description"]
      }
    },
    statComparison: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          statName: { type: Type.STRING },
          homeValue: { type: Type.STRING },
          awayValue: { type: Type.STRING },
          advantage: { type: Type.STRING, enum: ["Home", "Away", "Push"] }
        }
      }
    },
    injuries: { type: Type.ARRAY, items: { type: Type.STRING } },
    trends: { type: Type.ARRAY, items: { type: Type.STRING } },
    odds: {
      type: Type.OBJECT,
      properties: {
        winner: { type: Type.STRING },
        loser: { type: Type.STRING }
      }
    },
    props: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                player: { type: Type.STRING },
                line: { type: Type.STRING },
                stat: { type: Type.STRING },
                type: { type: Type.STRING, enum: ["MORE", "LESS"] },
                odds: { type: Type.STRING },
                probability: { type: Type.STRING },
                isElite179: { type: Type.BOOLEAN, description: "Flag for 179-point algorithm success." },
                ev: { type: Type.NUMBER, description: "Expected Value based on Sharp Line comparison." },
                analysis: { type: Type.STRING },
                lineComparison: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      book: { type: Type.STRING },
                      line: { type: Type.STRING },
                      odds: { type: Type.STRING }
                    }
                  }
                },
                performanceHistory: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      date: { type: Type.STRING },
                      opponent: { type: Type.STRING },
                      actualValue: { type: Type.STRING },
                      hit: { type: Type.BOOLEAN }
                    }
                  }
                }
            }
        }
    }
  },
  required: ["winner", "loser", "confidence", "confidenceScore", "eliteSignal179", "analysis", "gameScript", "statComparison", "injuries", "odds", "props", "trends"]
};

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `CRITICAL TASK: Search for ${sport} games occurring TODAY, ${today}. 

  PRIORITY: 
  1. LIVE GAMES (Show current real-time score and quarter).
  2. UPCOMING GAMES (Show official start time and real betting lines).

  Return STRICT JSON:
  { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "score": "optional string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        responseMimeType: 'application/json'
      }
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error) {
    console.error("Schedule Fetch Failed:", error);
    return [];
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gameContext = selectedGame.status === 'Live' ? `LIVE (${selectedGame.score}, ${selectedGame.time})` : `Start: ${selectedGame.time}`;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-3-pro-preview', // Upgraded to Pro for better reasoning
        config: {
          systemInstruction: `You are the PRO-N-OS 179-Point Simulation Engine.
          ALGORITHM: 
          1. Run 179 game simulations based on current injuries, weather, and momentum.
          2. Compare public lines vs. Sharp Lines (Pinnacle/Circa).
          3. Flag props as "isElite179" ONLY if they hit in >160 simulations.
          4. Find the "Guaranteed" edge where market mispricing exists.
          Return STRICT JSON.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
          tools: [{ googleSearch: {} }]
        }
      });

      const response = await newChat.sendMessage({ 
        message: `RUN 179-POINT SIMULATION: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam} (${gameContext}). Retrieve LIVE player availability and sharp market splits. Identify top 5 player props with elite hit probability.` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      console.error("Prediction Failed:", err);
      setError("Engine overwhelmed. Please try a manual sync.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;
    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    try {
        const response = await chat.sendMessage({ message: text });
        setMessages(prev => [...prev, { role: 'model', content: response.text || "I couldn't refine that data." }]);
    } catch (e) {
        setMessages(prev => [...prev, { role: 'model', content: "Engine timeout. Please refresh." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={() => setIsSettingsOpen(true)} onOpenToken={() => setIsTokenModalOpen(true)} />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>
        {error && (
            <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center animate-fade-in">
                <span className="text-xs font-bold uppercase tracking-tight">{error}</span>
                <button onClick={() => setError(null)} className="text-xl">&times;</button>
            </div>
        )}
        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                {selectedGame && (
                    <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                         <button onClick={handlePredict} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.5)] transform hover:scale-105 transition-all flex items-center gap-3">
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            RUN 179-POINT SIMULATION
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? <Loader /> : (
            <div className="space-y-4">
                 <button onClick={() => { setPrediction(null); setMessages([]); setChat(null); }} className="text-stone-500 hover:text-white mb-2 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg> Back to Feed
                 </button>
                 <ChatInterface messages={messages} isReplying={isReplying} onSendMessage={handleSendMessage} oddsFormat={settings.oddsFormat} pickSlip={pickSlip} onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} />
                 {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
            </div>
        )}
      </main>
      <PerformanceSidebar activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => handleSendMessage("Analyze my slip risk.")} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

