                                    onClick={() => onTogglePick && onTogglePick(prop)}
                                    className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${
                                        isInSlip ? 'bg-amber-500 text-black' : 'bg-zinc-900 text-zinc-600 border border-zinc-800 hover:border-zinc-600'
                                    }`}
                                >
                                    {isInSlip ? <CheckIcon className="w-6 h-6" /> : <PlusIcon className="w-6 h-6" />}
                                </button>
                            </div>

                            {prop.analysis && (
                                <p className="text-[11px] text-zinc-400 italic mb-4 border-l-2 border-zinc-800 pl-3 leading-relaxed">
                                    {prop.analysis}
                                </p>
                            )}

                            <div className="flex items-center gap-4">
                                <div className="flex-1 h-1 bg-black rounded-full overflow-hidden">
                                    <div className={`h-full ${isElite ? 'bg-amber-500' : 'bg-zinc-700'}`} style={{ width: prop.probability }}></div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <span className={`text-[10px] font-black uppercase tracking-widest ${isElite ? 'text-amber-500' : 'text-zinc-600'}`}>{prop.probability} Convergence</span>
                                    {prop.ev && (
                                        <span className="text-[9px] font-black text-green-500 uppercase tracking-tighter">+{prop.ev}% EV</span>
                                    )}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>

       {/* Laboratory Search */}
       <div className="bg-zinc-950 rounded-[2.5rem] border-2 border-dashed border-zinc-900 p-8 shadow-2xl">
           <div className="flex items-center gap-4 mb-8">
                <AnalyticsIcon className="w-7 h-7 text-amber-500" />
                <div>
                    <h3 className="text-sm font-black text-white uppercase tracking-[0.2em]">Matchup Lab</h3>
                    <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest">Verify Specific Defensive Floor</p>
                </div>
           </div>
           <form onSubmit={handleCustomAnalyze} className="flex flex-col md:flex-row gap-4">
               <input 
                  type="text" 
                  placeholder="Player (e.g. LeBron)"
                  value={customPlayer}
                  onChange={(e) => setCustomPlayer(e.target.value)}
                  className="flex-1 bg-black border-2 border-zinc-900 rounded-2xl px-6 py-4 text-sm font-black focus:ring-2 focus:ring-amber-500/50 outline-none text-white"
               />
               <input 
                  type="text" 
                  placeholder="Stat (e.g. 6.5 AST)"
                  value={customLine}
                  onChange={(e) => setCustomLine(e.target.value)}
                  className="flex-1 bg-black border-2 border-zinc-900 rounded-2xl px-6 py-4 text-sm font-black focus:ring-2 focus:ring-amber-500/50 outline-none text-white"
               />
               <button 
                  type="submit"
                  className="bg-amber-500 hover:bg-amber-400 text-black font-black px-10 py-4 rounded-2xl transition-all shadow-xl shadow-amber-500/10 uppercase tracking-widest"
               >
                  Test DVP
               </button>
           </form>
       </div>
    </div>
  );
});

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  const handlePredict = useCallback(async () => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const gameContext = selectedGame.status === 'Live' ? `LIVE (${selectedGame.score}, ${selectedGame.time})` : `Start: ${selectedGame.time}`;

    try {
      const newChat = ai.chats.create({ 
        model: 'gemini-3-pro-preview',
        config: {
          systemInstruction: `You are the PRO-N-OS 179-Point Simulation Engine.

          CRITICAL RULES:
          1. PROPS MUST include a numerical 'line' (e.g. "25.5") and a 'stat' category (e.g. "Points"). NEVER leave these blank.
          2. DEFENSIVE COMPARISON: Search for Defense vs Position (DvP) ranks. If Team A's defense is Rank #1 vs Assists, you MUST heavily weight a "LESS" outcome for the opposing PG's assists prop.
          3. 179-POINT SWEEP: Run 179 simulations. A pick is "isElite179" only if it hits >165 times AND is supported by a bottom-10 defensive mismatch (Rank #22-32).
          4. MARKET DIVERGANCE: Compare simulated probability vs real sharp odds (Pinnacle/Circa).

          Return STRICT JSON matching the provided schema.`,
          responseSchema: predictionSchema,
          responseMimeType: 'application/json',
          tools: [{ googleSearch: {} }]
        }
      });

      const response = await newChat.sendMessage({ 
        message: `PERFORM 179-POINT SIMULATION: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam}. 
        Identify the highest probability player props by comparing player's recent volume vs opponent's defensive rank for that specific category. 
        Example: "LeBron James OVER 8.5 Assists because opponent ranks #31 in assists allowed to SFs."` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      console.error("Prediction Failed:", err);
      setError("Engine overwhelmed. Please try a manual sync.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;
    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    try {
        const response = await chat.sendMessage({ message: text });
        setMessages(prev => [...prev, { role: 'model', content: response.text || "I couldn't refine that data." }]);
    } catch (e) {
        setMessages(prev => [...prev, { role: 'model', content: "Engine timeout. Please refresh." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header onOpenSettings={() => setIsSettingsOpen(true)} onOpenToken={() => setIsTokenModalOpen(true)} />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'pr-[300px]' : ''}`}>
        {error && (
            <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center animate-fade-in">
                <span className="text-xs font-bold uppercase tracking-tight">{error}</span>
                <button onClick={() => setError(null)} className="text-xl">&times;</button>
            </div>
        )}
        {!prediction && messages.length === 0 && !isLoading ? (
            <div className="space-y-8">
                <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                {selectedGame && (
                    <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                         <button onClick={handlePredict} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.5)] transform hover:scale-105 transition-all flex items-center gap-3">
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                            RUN 179-POINT SIMULATION
                        </button>
                    </div>
                )}
            </div>
        ) : isLoading ? <Loader /> : (
            <div className="space-y-4">
                 <button onClick={() => { setPrediction(null); setMessages([]); setChat(null); }} className="text-stone-500 hover:text-white mb-2 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg> Back to Feed
                 </button>
                 <ChatInterface messages={messages} isReplying={isReplying} onSendMessage={handleSendMessage} oddsFormat={settings.oddsFormat} pickSlip={pickSlip} onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} />
                 {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
            </div>
        )}
      </main>
      <PerformanceSidebar activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => handleSendMessage("Analyze my slip risk.")} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, SearchIcon, DoubleCheckIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string }> = {
    High: { bg: 'bg-green-950/40', text: 'text-green-400', border: 'border-green-500/40', accent: 'bg-green-500' },
    Medium: { bg: 'bg-amber-950/30', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500' },
    Low: { bg: 'bg-zinc-900/50', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-700' },
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, pickSlip = [], onTogglePick, onSearchPlayer }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');

  const [customPlayer, setCustomPlayer] = useState('');
  const [customLine, setCustomLine] = useState('');

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];
  const confidencePercentage = prediction.confidenceScore != null ? (prediction.confidenceScore * 100).toFixed(0) : 'N/A';

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return [...prediction.props]
      .filter(prop => {
          const matchesType = typeFilter === 'All' || prop.type === typeFilter;
          const matchesSearch = (prop.player || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                                (prop.stat || '').toLowerCase().includes(searchQuery.toLowerCase());
          return matchesType && matchesSearch;
      })
      .sort((a, b) => (b.isElite179 ? 1 : 0) - (a.isElite179 ? 1 : 0));
  }, [prediction.props, typeFilter, searchQuery]);

  const handleCustomAnalyze = (e: React.FormEvent) => {
      e.preventDefault();
      if (customPlayer && customLine && onSearchPlayer) {
          onSearchPlayer(`RUN 179-POINT SIMULATION for ${customPlayer} ${customLine}. Compare opponent's defensive rank for this specific stat.`);
          setCustomPlayer('');
          setCustomLine('');
      }
  };

  return (
    <div className="space-y-6 w-full animate-fade-in">
       {/* Matchup Insight Banner */}
       {prediction.matchupHighlight && (
          <div className="bg-zinc-900/80 border border-amber-500/20 px-6 py-3 rounded-2xl flex items-center gap-3 shadow-lg">
             <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></div>
             <span className="text-[10px] font-black uppercase tracking-widest text-amber-500/80">Matchup Edge:</span>
             <span className="text-[11px] font-bold text-white italic">{prediction.matchupHighlight}</span>
          </div>
       )}

       {/* 179 Elite Signal Banner */}
       {prediction.eliteSignal179 && (
          <div className="bg-gradient-to-r from-amber-500 to-amber-700 p-[2px] rounded-[2.5rem] shadow-[0_0_60px_rgba(245,158,11,0.2)]">
            <div className="bg-black rounded-[2.5rem] p-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 px-6 py-2 bg-amber-500 text-black text-[10px] font-black uppercase tracking-widest rounded-bl-3xl">179 ELITE SIGNAL</div>
                <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-amber-500/10 rounded-full flex items-center justify-center border border-amber-500/30">
                        <DoubleCheckIcon className="w-10 h-10 text-amber-500" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-black text-white italic tracking-tighter uppercase">High Floor Divergence</h3>
                        <p className="text-zinc-500 text-xs font-bold uppercase tracking-widest mt-1">Defensive Ranking Correlation Verified</p>
                    </div>
                </div>
            </div>
          </div>
       )}

       {/* Primary Prediction Banner */}
       <div className={`p-8 rounded-[2.5rem] border-2 ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-xl shadow-2xl relative overflow-hidden`}>
          <div className="flex flex-col md:flex-row justify-between items-center gap-8 relative z-10">
             <div className="flex items-center gap-6">
                 <div className="relative group">
                    <img 
                        src={`https://avatar.vercel.sh/${encodeURIComponent(prediction.winner)}.png?size=128`}
                        alt={prediction.winner}
                        className="w-24 h-24 rounded-full border-4 border-amber-500 shadow-2xl relative z-10"
                    />
                    <div className="absolute -bottom-2 -right-2 bg-green-500 rounded-full p-1.5 border-4 border-black z-20">
                        <CheckIcon className="w-4 h-4 text-black" />
                    </div>
                 </div>
                 <div>
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-amber-500/80">Engine Verdict</span>
                    <h2 className="text-4xl md:text-5xl font-black text-white mt-2 leading-none tracking-tighter">{prediction.winner}</h2>
                    <div className="flex items-center gap-3 mt-4">
                         <div className="h-1.5 w-32 bg-black/40 rounded-full overflow-hidden border border-white/5">
                            <div className={`h-full ${confidenceStyle.accent}`} style={{ width: `${confidencePercentage}%` }}></div>
                         </div>
                         <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">{confidencePercentage}% Hit Probability</span>
                    </div>
                 </div>
             </div>

             <div className="flex flex-col items-center md:items-end">
                 <div className={`px-6 py-3 rounded-2xl border-2 ${confidenceStyle.border} bg-black/60 backdrop-blur-md flex flex-col items-center shadow-lg`}>
                    <span className={`text-[10px] font-black uppercase tracking-[0.2em] mb-1 ${confidenceStyle.text}`}>Confidence</span>
                    <span className="text-3xl font-black text-white uppercase">{prediction.confidence}</span>
                 </div>
             </div>
          </div>

          <div className="mt-8 pt-6 border-t border-white/5">
              <p className="text-zinc-200 text-base md:text-lg leading-relaxed font-medium italic opacity-90">
                "{prediction.analysis}"
              </p>
          </div>
       </div>

       {/* Prop Market Feed */}
       <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 px-2">
                 <div className="flex items-center gap-3">
                    <AnalyticsIcon className="w-5 h-5 text-zinc-600" />
                    <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.3em]">
                        Verified Position Matchups
                    </h3>
                 </div>

                 <div className="flex items-center gap-1.5 bg-zinc-950 p-1.5 rounded-2xl border border-zinc-900 shadow-xl">
                    {['All', 'MORE', 'LESS'].map(filter => (
                        <button 
                            key={filter}
                            onClick={() => setTypeFilter(filter as any)} 
                            className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                                typeFilter === filter 
                                    ? 'bg-zinc-800 text-white' : 'text-zinc-600'
                            }`}
                        >
                            {filter}
                        </button>
                    ))}
                 </div>
            </div>

            <div className="grid gap-6">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat);
                    const isElite = prop.isElite179;
                    const matchup = prop.matchupMetric;

                    return (
                        <div 
                            key={index} 
                            className={`group relative bg-zinc-950 rounded-[2rem] border-2 p-6 transition-all duration-500 ${
                                isElite 
                                    ? 'border-amber-500 shadow-[0_0_40px_rgba(245,158,11,0.1)] bg-gradient-to-br from-zinc-900 to-black' 
                                    : 'border-zinc-900 hover:border-zinc-700'
                            }`}
                        >
                            {isElite && (
                                <div className="absolute -top-3 left-8 px-4 py-1 bg-amber-500 text-black text-[9px] font-black uppercase tracking-widest rounded-full border-2 border-black">
                                    ELITE DVP SIGNAL
                                </div>
                            )}

                            <div className="flex items-center justify-between mb-5">
                                <div className="flex items-center gap-6">
                                    <div className="relative">
                                        <img src={`https://avatar.vercel.sh/${encodeURIComponent(prop.player)}.png?size=80`} className={`w-16 h-16 rounded-full border-2 ${isElite ? 'border-amber-500' : 'border-zinc-800'}`} />
                                    </div>
                                    <div>
                                        <div className="flex flex-col gap-1 mb-1">
                                            <span className="font-black text-white text-xl tracking-tighter uppercase">{prop.player}</span>
                                            {matchup && (
                                                <div className="flex items-center gap-2">
                                                    <span className={`text-[9px] font-black px-2 py-0.5 rounded border uppercase tracking-widest ${
                                                        matchup.strength === 'Weak' ? 'bg-red-500/10 border-red-500/30 text-red-400' : 'bg-green-500/10 border-green-500/30 text-green-400'
                                                    }`}>
                                                        OPP RANK: {matchup.rank} VS {prop.stat}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className={`text-sm font-black px-3 py-1 rounded-lg uppercase tracking-widest border transition-all ${
                                                prop.type === 'MORE' ? 'bg-green-500/10 border-green-500/40 text-green-400' : 'bg-red-500/10 border-red-500/40 text-red-400'
                                            }`}>
                                                {prop.type === 'MORE' ? 'OVER' : 'UNDER'}
