                                            <div className="flex items-center gap-2">
                                                <span className="text-3xl font-black text-white tabular-nums">{prop.line || 'N/A'}</span>
                                                <span className="text-xs font-black text-zinc-500 uppercase tracking-widest">{prop.stat || 'STAT'}</span>
                                            </div>
                                            <span className="text-xs font-mono font-bold text-amber-500/50 bg-zinc-900 px-2 py-1 rounded-md">{prop.odds}</span>
                                        </div>
                                    </div>
                                </div>
