const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const predictionSchema = {
  type: Type.OBJECT,
  properties: {
    winner: { type: Type.STRING },
    loser: { type: Type.STRING },
    confidence: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
    confidenceScore: { type: Type.NUMBER },
    eliteSignal179: { 
      type: Type.BOOLEAN, 
      description: "True if the pick passes the 179-point variance simulation check (>92% hit rate) AND has a defensive ranking edge." 
    },
    analysis: { type: Type.STRING },
    matchupHighlight: { type: Type.STRING, description: "Detailed defensive ranking stat (e.g. 'Opponent allows 28.4 PPG to SFs, ranking #31 in the league')" },
    gameScript: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          phase: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ["phase", "description"]
      }
    },
    statComparison: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          statName: { type: Type.STRING },
          homeValue: { type: Type.STRING },
          awayValue: { type: Type.STRING },
          advantage: { type: Type.STRING, enum: ["Home", "Away", "Push"] }
        }
      }
    },
    injuries: { type: Type.ARRAY, items: { type: Type.STRING } },
    trends: { type: Type.ARRAY, items: { type: Type.STRING } },
    odds: {
      type: Type.OBJECT,
      properties: {
        winner: { type: Type.STRING },
        loser: { type: Type.STRING }
      }
    },
    props: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                player: { type: Type.STRING },
                line: { type: Type.STRING, description: "The EXACT numerical line, e.g. '24.5' or '6.5'" },
                stat: { type: Type.STRING, description: "The category, e.g. 'Points', 'Assists', 'Rebounds'" },
                type: { type: Type.STRING, enum: ["MORE", "LESS"] },
                odds: { type: Type.STRING },
                probability: { type: Type.STRING },
                isElite179: { type: Type.BOOLEAN },
                ev: { type: Type.NUMBER, description: "Expected Value percentage relative to market average" },
                performanceHistory: {
                  type: Type.ARRAY,
                  description: "Stats from the last 3 games played by this player for this specific stat category.",
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      date: { type: Type.STRING },
                      opponent: { type: Type.STRING },
                      actualValue: { type: Type.STRING },
                      hit: { type: Type.BOOLEAN, description: "Whether this actual value would have hit the 'MORE' or 'LESS' recommendation based on the current line." }
                    },
                    required: ["date", "opponent", "actualValue", "hit"]
                  }
                },
                matchupMetric: {
                  type: Type.OBJECT,
                  properties: {
                    rank: { type: Type.STRING, description: "Opponent's defensive rank vs this position/stat, e.g. '#29'" },
                    category: { type: Type.STRING },
                    strength: { type: Type.STRING, enum: ["Weak", "Strong", "Neutral"] }
                  }
                },
                analysis: { type: Type.STRING }
            },
            required: ["player", "line", "stat", "type", "probability", "analysis", "performanceHistory"]
        }
    }
  },
  required: ["winner", "loser", "confidence", "confidenceScore", "eliteSignal179", "analysis", "gameScript", "statComparison", "injuries", "odds", "props", "trends"]
};

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `CRITICAL TASK: Search for ${sport} games occurring TODAY, ${today}. 

  PRIORITY: 
  1. LIVE GAMES (Show current real-time score and quarter).
  2. UPCOMING GAMES (Show official start time and real betting lines).

  Return STRICT JSON:
  { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "score": "optional string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        responseMimeType: 'application/json'
      }
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error) {
    console.error("Schedule Fetch Failed:", error);
    return [];
  }
};

