                                </div>
                            )}

                            <div className="flex items-center justify-between mb-5">
                                <div className="flex items-center gap-6">
                                    <div className="relative">
                                        <img src={`https://avatar.vercel.sh/${encodeURIComponent(prop.player)}.png?size=100`} className={`w-20 h-20 rounded-full border-2 ${isElite ? 'border-amber-500' : 'border-zinc-800'}`} />
                                    </div>
                                    <div className="space-y-2">
                                        <div className="flex flex-col gap-1">
                                            <span className="font-black text-white text-2xl tracking-tighter uppercase">{prop.player}</span>
                                            <div className="flex items-center gap-2">
                                                {matchup && (
